import{_ as a,b as r,c as o,l as e}from"./chunks/framework.Bx9WV89s.js";const p=JSON.parse('{"title":"7.4 开发成本与选型决策","description":"","frontmatter":{},"headers":[],"relativePath":"compare/decision.md","filePath":"compare/decision.md","lastUpdated":1792642815000}'),d={name:"compare/decision.md"};function s(i,t,l,h,u,n){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="_7-4-开发成本与选型决策" tabindex="-1">7.4 开发成本与选型决策 <a class="header-anchor" href="#_7-4-开发成本与选型决策" aria-label="Permalink to &quot;7.4 开发成本与选型决策&quot;">​</a></h1><p>特性与性能只是选型的两本账，第三本账——开发成本——往往才是项目成败的决定因素：同样的需求，选错抽象层级可能让工期差出一个量级。本页把三本账合并，给出开发成本对比、场景到方案的映射表、五个问题的决策流程，以及真实项目中几乎必然出现的组合方案。这是对比分析模块的最后一页，目标是把前三页的所有结论压缩成可以立刻执行的决策动作。</p><h2 id="三本账怎么合并" tabindex="-1">三本账怎么合并 <a class="header-anchor" href="#三本账怎么合并" aria-label="Permalink to &quot;三本账怎么合并&quot;">​</a></h2><p>合并的顺序比合并的方法重要，推荐按&quot;排除、验证、权衡&quot;三步走：</p><ol><li><strong>用特性账排除</strong>：先做减法——要 3D 就排除全部 2D 方案，要矢量导出就排除纯位图方案，要对象编辑就排除没有对象模型的方案。剩下的候选通常不超过两个；</li><li><strong>用性能账验证</strong>：对剩下的候选，问&quot;我的图元数量乘以更新频率，落在它成本曲线的哪一段&quot;。7.3 的量级表与压测方法是这里的工具；拿不准就写个最小原型实测，半天原型换一周返工，永远值得；</li><li><strong>用成本账权衡</strong>：最后在都能胜任的候选里，选团队总成本最低的那个——体积、学习曲线、维护形态、招聘难度全部计入。</li></ol><p>三步各自的产出物也值得明确：排除步产出候选清单（通常只剩一两个），验证步产出一页实测记录或原型结论，权衡步产出一段写进评审纪要的决策理由。把过程产物留下来，选型就从&quot;某个高手的直觉&quot;变成&quot;团队可复用的资产&quot;——半年后面对相似需求，直接翻出上次的记录即可。</p><p>一个常见反模式是把顺序反过来：先被某个库的演示打动（成本账），硬着头皮做（性能账），最后发现核心需求根本满足不了（特性账）。先排除、再验证、后权衡，每一步都比上一步便宜。</p><p>三步的耗时量级也值得参考：排除通常在十分钟内完成（对照矩阵划列即可），验证视情况从一小时到半天（查量级表或做原型），权衡需要一次评审会（对齐五本账的权重）。整个流程走完一般不超过两天——相比选错技术后数周的返工，这是项目里性价比最高的两天。</p><h2 id="开发成本对比" tabindex="-1">开发成本对比 <a class="header-anchor" href="#开发成本对比" aria-label="Permalink to &quot;开发成本对比&quot;">​</a></h2><p>开发成本不是一笔钱，而是五本明细账：上手时间、依赖体积、生态与文档、团队技能要求、长期维护成本。同样一个需求，五本账的合计在不同团队手里可以差出数倍——因为团队自身的技能结构本身就是账本的乘数。</p><table tabindex="0"><thead><tr><th>成本维度</th><th>Canvas 2D</th><th>SVG</th><th>Fabric.js</th><th>ECharts</th><th>Three.js</th></tr></thead><tbody><tr><td>上手时间</td><td>几小时可出图</td><td>一两天掌握核心概念</td><td>一两天出编辑器雏形</td><td>几小时出图，精通配置需数周</td><td>数周建立 3D 心智模型</td></tr><tr><td>依赖体积</td><td>零依赖</td><td>零依赖</td><td>约 300 KB 级</td><td>完整包约 1 MB 级，按需可降至一半以下</td><td>约 600 KB 级</td></tr><tr><td>生态与文档</td><td>MDN 文档完善，示例极多</td><td>MDN 与规范完善</td><td>官方文档加社区示例</td><td>中文文档与示例生态最完善</td><td>官方手册加庞大社区与教程</td></tr><tr><td>团队技能要求</td><td>几何直觉与帧循环思维</td><td>CSS 功底与 XML 感觉</td><td>面向对象建模能力</td><td>数据结构与配置能力</td><td>线性代数与 GPU 基础概念</td></tr><tr><td>长期维护成本</td><td>低，API 高度稳定</td><td>低，标准极少变动</td><td>中，跟随框架大版本升级</td><td>低到中，大版本有配置迁移成本</td><td>高，版本迭代快且 API 变动频繁</td></tr></tbody></table><p>四条值得单独展开：</p><ul><li><strong>上手时间与交付风险是两回事。</strong> ECharts 几小时出图，但深度定制时要在庞大配置体系中摸索，风险后移；Canvas 2D 上手同样快，后续每一行都是自己的代码，风险可控但总量大。评估工期时要把&quot;定制深度&quot;作为乘数考虑进去；</li><li><strong>生态的&quot;语言含量&quot;直接影响排障效率。</strong> ECharts 的中文问答密度国内第一，报错几乎都有现成答案；Three.js 的优质内容以英文为主。团队的英语与检索能力，是真实的效率变量；</li><li><strong>长期维护成本常被忽略。</strong> Three.js 的迭代节奏快，锁定版本、审慎升级是常态；SVG 与 Canvas 2D 的代码写完后几乎可以十年不动。技术栈的生命周期应当与产品的生命周期匹配：活动页可以激进，十年期的政务系统请保守；</li><li><strong>五本账之间存在兑换关系。</strong> 体积大的库往往省下上手时间（ECharts），上手陡的库往往省下运行时成本（Three.js 之于裸 WebGL）——没有哪本账能单独决定胜负，合计最低者胜。评估时请把五本账写在同一张纸上打分，避免被最显眼的那一本带偏。</li></ul><h2 id="场景到方案映射" tabindex="-1">场景到方案映射 <a class="header-anchor" href="#场景到方案映射" aria-label="Permalink to &quot;场景到方案映射&quot;">​</a></h2><p>把常见业务场景直接映射到首选方案，这是全章最实用的一张表：</p><table tabindex="0"><thead><tr><th>业务场景</th><th>首选方案</th><th>理由一句话</th></tr></thead><tbody><tr><td>后台仪表盘与统计报表</td><td>ECharts</td><td>图表语义与交互开箱即用，开发效率碾压手写</td></tr><tr><td>实时监控大屏的图表区</td><td>ECharts</td><td>内置大数据优化手段，主题体系适配大屏</td></tr><tr><td>图形编辑器、在线白板、图片标注</td><td>Fabric.js</td><td>选中拖拽缩放成组与序列化全部现成</td></tr><tr><td>图标、插画、需无限缩放的矢量图</td><td>SVG</td><td>矢量本质加 CSS 可定制，且利于无障碍</td></tr><tr><td>粒子特效、大量动态图元、轻量小游戏</td><td>Canvas 2D</td><td>指令级自由，万级图元每帧重绘仍流畅</td></tr><tr><td>更大规模的 2D 动态场景</td><td>WebGL，可经 PixiJS 等 2D 引擎</td><td>GPU 并行突破 CPU 指令数的线性瓶颈</td></tr><tr><td>3D 产品展示、数字孪生、大屏 3D 模块</td><td>Three.js</td><td>WebGL 生态最成熟的场景图引擎</td></tr><tr><td>复杂营销动效</td><td>CSS 与 SVG 动画，复杂时用 Lottie</td><td>Lottie 直接播放设计稿产物，设计开发分离</td></tr><tr><td>大规模图关系可视化</td><td>ECharts graph 或 D3 力导向</td><td>交互浅用前者，布局深度定制用后者</td></tr><tr><td>地理可视化</td><td>Leaflet 与 MapLibre 等地图库，大屏可叠加 ECharts GL</td><td>投影与底图是专业问题，交给专业方案</td></tr><tr><td>打印优先的报表与票据</td><td>SVG</td><td>矢量输出保证任何分辨率下清晰</td></tr><tr><td>数据艺术与生成艺术</td><td>Canvas 2D，追求效果上 WebGL 着色器</td><td>创作自由度优先于一切工程考量</td></tr></tbody></table><p>读表时注意：映射给的是&quot;首选&quot;，不是&quot;唯一解&quot;。真实约束（团队现有技能、已有依赖、交付时间）随时可以合理地推翻首选——这正是下一节决策流程存在的意义。</p><p>再补一个使用提醒：表中的场景描述写的是&quot;典型形态&quot;，你的需求往往是几个场景的叠加——&quot;带地图打点的实时仪表盘&quot;同时命中第一、第二与最后一行。遇到叠加场景，按区域拆开查表，再把各行的首选组合起来，而不是强行找一行把全部需求塞进去。</p><p>最后提醒表格的时效性：可视化生态仍在演进，映射关系不是刻在石头上的——图表库可能新增系列类型，引擎可能重构模块体系，某个新库也可能突然成为某场景的首选。建议每半年到一年对照生态动态复核一次这张表，尤其是你长期维护的产品线所命中的那几行；把复核结论补充进团队自己的版本，这张表才会越用越准。</p><h2 id="选型决策流程" tabindex="-1">选型决策流程 <a class="header-anchor" href="#选型决策流程" aria-label="Permalink to &quot;选型决策流程&quot;">​</a></h2><p>五个问题按顺序回答，绝大多数需求会在中途落定答案。每个问题的分支都指向具体技术。问题的顺序经过设计：前面的问题排除面最大（3D 与否直接砍掉一半候选），越往后越精细——按这个顺序走，每一步都在最便宜的时候做最贵的排除。</p><h3 id="问题一-需要-3d-吗" tabindex="-1">问题一：需要 3D 吗 <a class="header-anchor" href="#问题一-需要-3d-吗" aria-label="Permalink to &quot;问题一：需要 3D 吗&quot;">​</a></h3><p>这是分水岭最大的一问，所以放在最前面。</p><ul><li>需要——选 <a href="/viz-guide-site/three/scene.html">Three.js</a>，并顺手评估 Babylon.js 作为备选。不要尝试用 Canvas 2D 手写 3D 投影，工程成本远高于学习引擎；也不要因为&quot;图表库里有个 3D 柱状图&quot;就把 3D 需求降级，假 3D 的交互与光照一眼穿帮；</li><li>不需要——进入下一问。</li></ul><p>判断&quot;需要 3D&quot;要听需求方的动机：是数据本身有三维结构（户型、分子、地形、设备），还是只是&quot;想酷一点&quot;。前者是硬需求，后者值得用 2D 加好的设计先交付一版——3D 的成本不仅在建模渲染，还在持续的素材生产管线。</p><h3 id="问题二-是标准统计图表吗" tabindex="-1">问题二：是标准统计图表吗 <a class="header-anchor" href="#问题二-是标准统计图表吗" aria-label="Permalink to &quot;问题二：是标准统计图表吗&quot;">​</a></h3><p>判断标准很朴素：柱状、折线、饼、散点、雷达、漏斗、地图热力这些类型，是否能在图表库的目录里直接找到。</p><ul><li>是——选 <a href="/viz-guide-site/echarts/quick-start.html">ECharts</a>，把工期花在数据与业务上，而不是重造坐标系。&quot;图表类型在目录里，但设计师改了很多样式&quot;仍然选它，ECharts 的主题与配置体系比想象中能装；</li><li>不是——进入下一问。</li></ul><p>一个提醒：不要在这一问上自欺欺人。把&quot;流程编排画布&quot;看成&quot;图表&quot;，会在第三周发现自己在配置项里模拟拖拽；把&quot;带一千个自定义标记的地图&quot;看成&quot;自由绘制&quot;，会错过 ECharts 地图系列现成的一切。先翻翻图表库目录再回答。</p><h3 id="问题三-需要对象级交互编辑吗" tabindex="-1">问题三：需要对象级交互编辑吗 <a class="header-anchor" href="#问题三-需要对象级交互编辑吗" aria-label="Permalink to &quot;问题三：需要对象级交互编辑吗&quot;">​</a></h3><p>即用户是否要选中、拖拽、缩放、旋转、成组图形对象，是否需要把画布内容序列化保存。编辑器与展示器的分水岭就在这一问。</p><ul><li>需要——选 <a href="/viz-guide-site/fabric/fundamentals.html">Fabric.js</a>，或评估同类 Konva。手写这套交互的成本以周计，而库已经替你做完，包括控制点、变换矩阵与撤销重做的数据基础；</li><li>不需要——进入下一问。</li></ul><p>区分&quot;交互&quot;与&quot;编辑&quot;是关键：hover 高亮、点击下钻是交互，图表库与 SVG 原生就能给；拖动一个图形改变它的几何属性才是编辑，那必须有一个可寻址的对象模型——这正是 Fabric.js 存在的意义。</p><p>还有一个进阶信号值得留意：需求里一旦出现&quot;多人协同编辑&quot;&quot;历史版本回放&quot;&quot;把画布分享给别人继续改&quot;这类字眼，序列化能力就从加分项变成硬需求——Fabric.js 的 JSON 场景模型的价值会进一步放大，而手写 Canvas 方案的成本估算要再加上数据模型设计这一大笔。</p><h3 id="问题四-动态图元的规模与更新频率如何" tabindex="-1">问题四：动态图元的规模与更新频率如何 <a class="header-anchor" href="#问题四-动态图元的规模与更新频率如何" aria-label="Permalink to &quot;问题四：动态图元的规模与更新频率如何&quot;">​</a></h3><p>把&quot;图元数量&quot;与&quot;是否每帧更新&quot;相乘，定位你在成本曲线上的位置（依据见 <a href="/viz-guide-site/compare/performance.html">7.3 性能对比与实测</a>）：</p><ul><li>数十到数百个图元，或更新频率低——<a href="/viz-guide-site/svg/fundamentals.html">SVG</a> 与 DOM 都轻松胜任，按交互与无障碍需求挑选；</li><li>数千到数万个每帧更新的图元——选 <a href="/viz-guide-site/canvas/fundamentals.html">Canvas 2D</a>；</li><li>数万以上且仍要每帧更新——上 WebGL 方案，2D 场景可经 PixiJS 等引擎，避免直写裸 WebGL。</li></ul><p>拿不准数量级时，数一数真实数据：列表页的平均行数、监控指标的采样频率、关系图的节点中位数。选型会上&quot;大概很多吧&quot;是最危险的输入，真实数字常常比印象小一个量级——也可能大一个量级。</p><p>频率也要像数量一样落到数字。&quot;实时更新&quot;是一个危险词汇：它是每 100 毫秒一刷，还是每 5 秒一刷，成本相差 50 倍，选型结论可能完全不同。评审时让需求方给出具体的刷新率与峰值场景，最好写进需求文档——这两个数字日后还是性能验收的依据，早定早受益。</p><h3 id="问题五-是否要求矢量导出、打印或无障碍" tabindex="-1">问题五：是否要求矢量导出、打印或无障碍 <a class="header-anchor" href="#问题五-是否要求矢量导出、打印或无障碍" aria-label="Permalink to &quot;问题五：是否要求矢量导出、打印或无障碍&quot;">​</a></h3><ul><li>是——优先 SVG，并把问题四中的规模上限往下调一档来评估：无障碍与矢量导出是 SVG 的结构性优势，值得为它收缩性能预期；</li><li>否——按问题四的答案执行。</li></ul><p>无障碍一项尤其容易被漏问。面向公众或政务的产品常有合规要求，SVG 的真实文本节点能让屏幕阅读器直接工作，Canvas 则需要额外的 fallback 内容；需求评审时多问这一句，能避免上线前的推倒重来。</p><p>打印需求要问得更细：是浏览器直接打印，是导出 PDF 归档，还是送印刷厂制版？三者的要求逐级升高——浏览器打印位图尚可凑合，PDF 归档开始在意缩放清晰度，制版则非矢量不可。SVG 在三档下通吃，位图方案到了后两档就会露馅；提前问清，好过交付前一周才发现印出来的展板全是锯齿。</p><p>五个问题走完仍无结论的需求，通常是语义尚未厘清：回到需求侧，先回答&quot;用户看到的到底是什么、要操作什么&quot;，再重走流程。</p><h2 id="四个完整的选型推演" tabindex="-1">四个完整的选型推演 <a class="header-anchor" href="#四个完整的选型推演" aria-label="Permalink to &quot;四个完整的选型推演&quot;">​</a></h2><p>把五问连起来跑几遍，看结论如何自然浮现。</p><p>四个推演分别覆盖四种典型局面：组合方案收场的、流程中途就收束的、五问之外的因素决胜的、以及答案落在生态成员而非五大技术上的。读的时候建议先遮住结论，自己按五问推一遍再对照——推演最大的价值在于校准你自己的判断路径，而不在于记住某个具体答案。</p><p><strong>推演一：运维数据大屏。</strong> 问题一：需要 3D 吗——中央要机房三维视图，要；但四周的趋势折线、占比饼图是标准统计图表。结论：组合方案，Three.js 负责中央场景，ECharts 负责全部统计图表，正是后文的组合模式一——五问不是单选开关，回答完每个区域各归其位。</p><p><strong>推演二：在线白板。</strong> 问题一：不需要 3D。问题二：不是标准图表，是自由图形。问题三：需要对象级编辑，这正是产品核心。结论：Fabric.js，问题四与问题五根本不用问——流程在中途就收束了，这是常态而非例外。</p><p><strong>推演三：营销活动落地页。</strong> 前三个问题全否。问题四：几十个装饰元素加一段复杂动效，规模很小。问题五：无硬性要求。此时技术差异已经不重要，决定因素滑向五问之外：设计师的动效稿如何高保真落地？结论：CSS 与 SVG 动画为主，复杂段落用 Lottie 直接播放设计产物。</p><p><strong>推演四：数据新闻专题页。</strong> 问题一：不需要 3D。问题二：编辑要的图形在图表库目录里找不到——河流图、弦图、定制地图投影。问题三：不需要编辑。问题四：数百个图元，低频更新。结论：SVG 加 D3——这个格子在矩阵里一直空着，等的就是&quot;标准图表之外、规模不大、表达要完全自由&quot;的需求。</p><p>四个推演走完可以发现规律：五问并不总是通向五大技术，有时通向组合，有时通向生态成员——流程的价值在于排除与排序，而不在于背答案。建议挑一个你手头真实的需求，现在就按这五步走一遍：第一次走会有些磕绊，走到第三次，整个流程会压缩成十几秒的直觉。</p><h2 id="组合方案-真实项目的常态" tabindex="-1">组合方案：真实项目的常态 <a class="header-anchor" href="#组合方案-真实项目的常态" aria-label="Permalink to &quot;组合方案：真实项目的常态&quot;">​</a></h2><p>单一技术打天下的项目几乎不存在。三个有代表性的组合模式：</p><p>先说明白：组合不是没有代价——多一份依赖体积、两套视觉语言需要人工对齐、技术边界处需要明确的数据契约。但与&quot;用单一技术硬扛所有需求&quot;相比，这些代价几乎总是更便宜：硬扛的账单以周为单位支付在对抗框架上，组合的账单以天为单位支付在边界设计上。下面三个模式的价值，正在于把边界划在了每种技术成本最低的位置。</p><h3 id="模式一-echarts-图表加-three-js-3d-模块的同屏大屏" tabindex="-1">模式一：ECharts 图表加 Three.js 3D 模块的同屏大屏 <a class="header-anchor" href="#模式一-echarts-图表加-three-js-3d-模块的同屏大屏" aria-label="Permalink to &quot;模式一：ECharts 图表加 Three.js 3D 模块的同屏大屏&quot;">​</a></h3><p>监控大屏常见&quot;中央 3D 场景加四周统计图表&quot;的布局。边界划分原则：<strong>按语义分工，不按面积分工</strong>——凡是统计语义的图表（趋势、占比、排行）全部归 ECharts，享受其交互与主题体系；中央需要空间表达的 3D 场景归 Three.js。两者各自持有独立 canvas，布局用普通 CSS Grid 完成，数据层通过同一状态源驱动。</p><p>工程上注意两点：其一，3D 区域是功耗大户，要给它设定帧率预算（例如数据静默时降低渲染频率），避免拖垮同屏图表的动画；其二，视觉语言（配色、字号、发光风格）要在两个技术栈间人工对齐，这是组合方案最主要的隐性成本。</p><p>这个模式的适用边界也很清楚：3D 场景只是大屏的一个&quot;区域&quot;而非全部——如果整个页面都是 3D 世界（数字孪生的漫游视角），图表就应该以浮层形式进入 3D 场景，主从关系随之反转。</p><h3 id="模式二-svg-图标加-canvas-主画布的白板应用" tabindex="-1">模式二：SVG 图标加 Canvas 主画布的白板应用 <a class="header-anchor" href="#模式二-svg-图标加-canvas-主画布的白板应用" aria-label="Permalink to &quot;模式二：SVG 图标加 Canvas 主画布的白板应用&quot;">​</a></h3><p>白板与编辑器类产品的典型结构：工具栏、属性面板用普通 HTML 加 SVG 图标——图标需要无限缩放与换肤，SVG 是当然之选；画布主区域归 Canvas 2D 或 Fabric.js——那里有高频重绘与复杂交互。两层各司其职，SVG 图标还可以通过 drawImage 贴进 canvas 内部，作为画布上的图形资源复用。</p><p>这个模式的隐性收益是设计资产的单一来源：工具栏图标与画布内图形出自同一份 SVG 文件，改一次设计，两处同时更新——组合架构不仅没有带来双倍维护，反而消灭了重复资产。</p><p>边界划分原则与模式一相同：<strong>静态 UI 归 DOM 与 SVG，高频绘制归 Canvas，编辑语义归 Fabric.js</strong>。按&quot;更新频率与交互深度&quot;切分区域，而不是按技术洁癖强求全站统一——统一的是设计语言与数据流，不是渲染技术。</p><h3 id="模式三-svg-图表加-html-表格的可访问报表" tabindex="-1">模式三：SVG 图表加 HTML 表格的可访问报表 <a class="header-anchor" href="#模式三-svg-图表加-html-表格的可访问报表" aria-label="Permalink to &quot;模式三：SVG 图表加 HTML 表格的可访问报表&quot;">​</a></h3><p>政务、金融、教育类产品的报表常有合规要求。一种稳妥结构：图表本体用 SVG（或 ECharts 的 SVG 渲染器）渲染，文本真实可选中；图表下方配一个默认折叠的 HTML 数据表格，屏幕阅读器与键盘用户可以完整遍历数据；打印样式表里隐藏交互控件、保留矢量图形。这个组合几乎不增加开发量，却把可访问性从&quot;补做&quot;变成了&quot;白得&quot;。</p><p>要注意它的规模边界：SVG 渲染器只在中小数据量下成立，数据量涨上去之后应退回 Canvas 渲染器并保留 HTML 表格兜底——表格才是这个模式里不可让渡的部分。</p><p>三个模式背后是同一条结构原则：<strong>每种技术只负责它成本最低的那一层，层与层之间用数据而非像素通信</strong>。只要守住这条原则，组合的成员可以随需求自由替换——ECharts 换成 Chart.js、Three.js 换成 Babylon.js，架构纹丝不动。</p><h2 id="团队与组织因素" tabindex="-1">团队与组织因素 <a class="header-anchor" href="#团队与组织因素" aria-label="Permalink to &quot;团队与组织因素&quot;">​</a></h2><p>技术账之外，人的账同样真实，经常直接改写技术结论——同样的需求交给两个不同团队，正确答案可以不同：</p><ul><li><strong>技能惯性是资产不是包袱</strong>：团队已熟练的栈，交付速度与质量都有复利；除非硬性需求不满足，&quot;用熟不用新&quot;通常是正确答案；</li><li><strong>已有依赖降低边际成本</strong>：项目里已有 ECharts，新增图表的边际成本接近零；为它再引入一个同类图表库是双重维护负担；</li><li><strong>招聘与交接</strong>：ECharts 与 Canvas 的候选人池远大于 Three.js 与 D3；关键模块选用冷门技术，要把&quot;作者离职&quot;明确列为风险项；</li><li><strong>设计与开发的协作流</strong>：SVG 资产设计师可直接产出与修改，Canvas 图形则完全依赖开发实现——设计迭代频繁的项目，图形资产的可交接性应计入成本。</li><li><strong>客户与运行环境是硬约束</strong>：政务、国企、教育类客户的浏览器版本、内网隔离、国产化终端都可能直接划掉候选——选型评估里&quot;目标环境实际能跑什么&quot;应与&quot;我们想用什么&quot;并列，交付前才发现环境不兼容是最贵的意外。</li></ul><p>这些因素不该出现在技术对比文章里，却真实决定项目结局。成熟的选型报告会把技术结论与组织约束并列写出：结论是&quot;应该选 X&quot;，约束是&quot;团队只会 Y&quot;，折中方案与补课计划紧随其后——这比假装约束不存在要诚实得多，也可执行得多。</p><h2 id="当需求横跨多个格子" tabindex="-1">当需求横跨多个格子 <a class="header-anchor" href="#当需求横跨多个格子" aria-label="Permalink to &quot;当需求横跨多个格子&quot;">​</a></h2><p>有些需求五个问题答完仍横跨多种技术——比如&quot;大数据量图表，且每个点都要能拖拽编辑&quot;，前端、交互、数据三方的答案各自成立却互不兼容。此时的正确动作不是硬选，而是拆分：</p><ol><li><strong>按图层拆</strong>：底层渲染归 Canvas 或 ECharts，交互层用透明 SVG 或 DOM 覆盖物承载拖拽句柄，命中检测由数据索引完成，编辑的只有被操作的那几个对象；</li><li><strong>按阶段拆</strong>：编辑态与展示态用不同实现——编辑态对象少、交互深，用 Fabric.js；发布态数据大、交互浅，把编辑产出的数据用 ECharts 或 Canvas 重新渲染；</li><li><strong>做个原型再定</strong>：横跨格子的需求，任何纸面分析都不如半天的最小原型可靠；原型要带着真实数据量级去做，否则验证不了性能这一半。</li></ol><p>组合不是妥协，是把每个子问题交给成本最低的技术——这本来就是本章分类框架的用途。</p><h2 id="把五问用在评审会上" tabindex="-1">把五问用在评审会上 <a class="header-anchor" href="#把五问用在评审会上" aria-label="Permalink to &quot;把五问用在评审会上&quot;">​</a></h2><p>五问的价值在多人评审时翻倍，因为它给不同角色提供了共同语言与议程：</p><ul><li>产品经理回答需求语义（问题一与二），设计回答交互深度（问题三），前端回答规模与频率（问题四），合规与运营回答导出与无障碍（问题五）——每个问题都有明确的责任人；</li><li>每逢分歧，回到对应的问题编号，而不是泛泛争论&quot;哪个框架更好&quot;——评审经验里，分歧几乎都来自对需求理解的不一致，而非对技术判断的不一致；</li><li>把答案与结论写进评审纪要：三个月后有人问&quot;当初为什么选它&quot;，纪要里的五问答案就是最硬的依据，也能直接复用到下一个相似需求。</li></ul><p>一个落地技巧：把五问做成评审模板固定下来，新需求先填表再开会。会议因此从&quot;头脑风暴&quot;变成&quot;逐项确认&quot;，时长常常缩短一半以上；更重要的是，填表的过程会逼着需求方把模糊的形容词换成具体的数字——这一步的价值，经常超过技术结论本身。</p><h2 id="常见选型错误" tabindex="-1">常见选型错误 <a class="header-anchor" href="#常见选型错误" aria-label="Permalink to &quot;常见选型错误&quot;">​</a></h2><p>最后列出八种反复在真实项目中出现的错误，每一条都对应一次返工：</p><ul><li><strong>用 div 堆大数据量图表</strong>：数百个节点后 Layout 崩塌，页面随数据增长越来越卡。正解：数据图表交给 ECharts，自定义图形交给 Canvas；</li><li><strong>用 ECharts 做图形编辑器</strong>：配置体系没有&quot;自由对象&quot;的概念，每一个拖拽需求都在对抗框架。正解：Fabric.js；</li><li><strong>用 Three.js 做 2D 报表</strong>：杀鸡用牛刀且更贵——文本、坐标轴、提示框全部要重造。正解：2D 需求不碰 3D 引擎；</li><li><strong>迷信 Canvas 性能，一切图表都手写</strong>：几百个图元的场景用 Canvas，换来交互与无障碍全部自建，性能优势根本用不上。正解：小规模优先 SVG；</li><li><strong>忽视体积与功耗</strong>：完整引入三大库做一张活动页，低端机加载白屏、手机发烫。正解：按需引入，弱设备准备降级方案；</li><li><strong>为&quot;未来可能的 3D&quot;提前引入重型引擎</strong>：需求从未到来，维护成本先行支付。正解：按当前需求选型，组合架构随时能加新成员；</li><li><strong>把动画库当可视化库</strong>：Lottie 播放的是设计好的固定动画，数据变化驱动不了它。正解：数据驱动的画面用渲染技术，装饰性动效用 Lottie，两者同屏共存毫无问题；</li><li><strong>先做技术调研再读需求</strong>：拿着锤子找钉子，调研报告写得越厚，越舍不得放弃已经投入的沉没成本。正解：需求五问在先，技术调研在后。</li></ul><p>这八条的共同根源，是把&quot;技术的新潮程度&quot;或&quot;个人的熟悉程度&quot;误当成了&quot;与需求的匹配程度&quot;。避免它们的办法不需要更多技术知识，只需要老老实实走完前文的五问——流程存在的意义，就是替你在头脑发热时踩刹车。</p><h2 id="关于演进-选型不是终身承诺" tabindex="-1">关于演进：选型不是终身承诺 <a class="header-anchor" href="#关于演进-选型不是终身承诺" aria-label="Permalink to &quot;关于演进：选型不是终身承诺&quot;">​</a></h2><p>需求会长大，技术栈也应当允许长大。四条常见的演进路径，提前知道它们存在，能让今天的选择少一些患得患失：</p><ul><li><strong>从 ECharts 起步，触顶后下沉渲染层</strong>：先用配置快速交付，当某个图表的定制需求反复撞墙时，把这一个图表用 Canvas 手写替换——页面其余部分纹丝不动。抽象层级是可以逐图表下调的，不是全站决定；</li><li><strong>从 SVG 原型起步，数据涨后换 Canvas</strong>：原型期数据量小，SVG 的交互便利帮助快速验证产品；数据量涨过阈值后，保持同一套数据到视觉的映射函数，只替换渲染执行层。映射设计与渲染技术解耦，是这种迁移便宜的前提；</li><li><strong>从单技术起步，按区域长出新成员</strong>：大屏先上 ECharts 图表区，下一期再加 Three.js 的 3D 模块——组合架构最大的优点是演进可以局部发生，新需求不需要推翻旧资产；</li><li><strong>反向演进同样成立</strong>：为赶工期引入的重型方案，在产品稳定后可以瘦身——比如把只用了三个图表类型的 ECharts 完整包换成按需构建，把演示期引入的 3D 模块在确认无人问津后干脆下线。演进的方向是匹配当前需求，不是单向加码。</li></ul><p>把&quot;未来可能要迁移&quot;写进今天的代码结构里（数据层与渲染层分离、映射函数独立可测），演进真的到来时，成本只是一个模块的重写，而不是整个项目的重来。</p><h2 id="一页速查" tabindex="-1">一页速查 <a class="header-anchor" href="#一页速查" aria-label="Permalink to &quot;一页速查&quot;">​</a></h2><p>把全章压缩成五行，贴在工位上。两张表配合用：&quot;什么时候用&quot;表做正向排除——逐行对照需求，不满足的行整行划掉；&quot;什么时候不用&quot;表做反向校验——得出初步结论后回查一遍，一旦命中&quot;不用&quot;行，立刻回头重走五问。正向快、反向稳，两分钟完成一次自检。</p><table tabindex="0"><thead><tr><th>技术</th><th>什么时候用</th></tr></thead><tbody><tr><td>Canvas 2D</td><td>要自己掌控每一帧画面，图元成千上万或要逐像素处理时</td></tr><tr><td>SVG</td><td>图元不多，但要矢量缩放、要 CSS、要图元级事件与无障碍时</td></tr><tr><td>Fabric.js</td><td>做的是&quot;编辑器&quot;而不是&quot;图表&quot;，用户要操作画布上的对象时</td></tr><tr><td>ECharts</td><td>做的是标准统计图表，且要快速交付与丰富交互时</td></tr><tr><td>Three.js</td><td>需求里出现 3D 两个字时</td></tr></tbody></table><p>什么时候<strong>不用</strong>它们，同样值得五行：</p><table tabindex="0"><thead><tr><th>技术</th><th>什么时候不用</th></tr></thead><tbody><tr><td>Canvas 2D</td><td>图元少而交互深，或有无障碍与文本排版要求时</td></tr><tr><td>SVG</td><td>每帧更新数千以上图元的高频动态场景</td></tr><tr><td>Fabric.js</td><td>只画几个静态图形，或做纯展示型数据图表时</td></tr><tr><td>ECharts</td><td>需求是自由图形编辑、3D 或高度艺术化表达时</td></tr><tr><td>Three.js</td><td>常规 2D 页面，以及对体积功耗敏感的弱设备场景</td></tr></tbody></table><p>速查表的定位是&quot;第一反应&quot;，不是&quot;最终裁决&quot;：它帮你在讨论的头三十秒排除明显错误的方向，真正的结论仍要经过前五问的验证。把两张表贴在工位上，把五问记在心里，这就是本章希望你带走的全部。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>选型是三本账的合并计算：特性决定&quot;能不能做&quot;，性能决定&quot;做得动不动&quot;，开发成本决定&quot;多久做完、好不好养&quot;；合并的顺序是先排除、再验证、后权衡。决策流程压缩为五问：要不要 3D、是不是标准图表、要不要对象级编辑、图元规模多大、要不要矢量与无障碍——按顺序回答，答案通常在中途自己浮现。真实项目几乎都是组合架构，按更新频率与交互深度切分技术边界，比追求全站技术统一更重要。</p><p>至此对比分析模块结束：从 <a href="/viz-guide-site/compare/taxonomy.html">7.1 的分类框架</a> 到 <a href="/viz-guide-site/compare/features.html">7.2 的特性矩阵</a>、<a href="/viz-guide-site/compare/performance.html">7.3 的性能实测</a>，再到本页的决策流程，四页内容构成一个闭环——剩下的，是回到各技术章节把选定的武器练熟：<a href="/viz-guide-site/canvas/fundamentals.html">Canvas 2D</a>、<a href="/viz-guide-site/svg/fundamentals.html">SVG</a>、<a href="/viz-guide-site/fabric/fundamentals.html">Fabric.js</a>、<a href="/viz-guide-site/echarts/quick-start.html">ECharts</a>、<a href="/viz-guide-site/three/scene.html">Three.js</a>。</p>',96)])])}const c=a(d,[["render",s]]);export{p as __pageData,c as default};
